/// <summary>
/// designed from AVA
/// </summary>
/// <returns>AVAMSQQueueId</returns>
public AVAMSQQueueId salesOrderInvoiceSendOut()
{
    AVAMSQQueueId   avaMSQQueueId;
    boolean         isTransferred = false;

    avaMSQQueueId = next salesOrderInvoiceSendOut();
    if (!avaMSQQueueId)
    {
        if(custInvoiceJour.RecId && custInvoiceJour.AVAEDITransfer == NoYes::Yes)
        {
            if (custInvoiceJour.SalesOriginId != '') // the first loop for assignments with defined originId, the second loop for  assignments with originId = empty (requesten from solution architector)
            {
                avaMSQQueueId = AVAMSQProcessingQueue::uploadExportFromProcessTOS(AVAMSQOutIntProcesses::AVAEDISalesInvoiceOut,
                                                                                   int642Str(custInvoiceJour.RecId),
                                                                                   CustVendACType::Cust,
                                                                                   custInvoiceJour.OrderAccount,
                                                                                   '',
                                                                                   '',custInvoiceJour.InvoiceId,
                                                                                   custInvoiceJour.InvoiceAmount,custInvoiceJour.SalesOriginId);
                if (avaMSQQueueId)
                {
                    isTransferred = true;
                    Info(strFmt("@AVAEDI:EDITransferToMSQ", AVAMSQOutIntProcesses::AVAEDISalesInvoiceOut, custInvoiceJour.InvoiceId, avaMSQQueueId));
                }
            }
            avaMSQQueueId = '';
            avaMSQQueueId = AVAMSQProcessingQueue::uploadExportFromProcessTOS(AVAMSQOutIntProcesses::AVAEDISalesInvoiceOut,
                                                                               int642Str(custInvoiceJour.RecId),
                                                                               CustVendACType::Cust,
                                                                               custInvoiceJour.OrderAccount,
                                                                               '',
                                                                               '',custInvoiceJour.InvoiceId,
                                                                               custInvoiceJour.InvoiceAmount,'');
            if (avaMSQQueueId)
            {
                isTransferred = true;
                Info(strFmt("@AVAEDI:EDITransferToMSQ", AVAMSQOutIntProcesses::AVAEDISalesInvoiceOut, custInvoiceJour.InvoiceId, avaMSQQueueId));
            }

            custInvoiceJour.AVAEDITransfer = isTransferred;

        }
    }

    return avaMSQQueueId;
}
